{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "Since the coronavirus disease 2019 (COVID-19) outbreak was reported in December 2019, a huge number of clinical studies have been initiated... The number of trials recorded in clinical trial registries is proliferating exponentially, with many independent research efforts designed to answer similar questions. ... independent trials with small sample sizes and underrepresentation of some patient populations limit the acquisition of substantive evidence to assess the effects and applicability of the many diagnostic methods, therapeutic and prophylactic strategies targeted to address the COVID-19 pandemic",
      "reason": "The text describes the rapid proliferation of COVID-19 clinical trials and the uncertainty/limitations caused by independent, small-scale, and uncoordinated research efforts."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_4",
      "quote": "As the research landscape becomes increasingly saturated, better coordination in study design, dosing strategies and pooling data for subsequent metanalyses, are needed to ensure definitive answers can be translated into clinical practice as rapidly as possible. Tools that allow researchers to review the diversity of interventions already underway are critical in facilitating collaboration, harmonisation, partnerships and open access research.",
      "reason": "The text explains the need for the review as a tool to facilitate coordination, collaboration, and harmonization in a saturated research landscape."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not indicate that this is an update or replication of a specific previous systematic review, nor does it suggest that similar systematic reviews exist that necessitate a justification for this specific one beyond the general need for the living review method."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of clinical trial registrations, not a review of the effects of a specific intervention; therefore, a mechanism of action is not applicable."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a systematic review of clinical trial registrations, not a complex intervention or delivery context study; therefore, a logic model is not applicable."
    }
  ],
  "confidence": 100
}

{
  "item_id": "PRISMA_2020_4",
  "elements": [
    {
      "element_id": "prisma_2020_4_e1",
      "status": "PARTIAL",
      "chunk_id": "text_36",
      "quote": "This is a living systematic review of clinical study registrations (clinical trials and otherwise) for the diagnosis, treatment and prevention of COVID-19",
      "reason": "The review's objective is stated (to review clinical study registrations for the diagnosis, treatment, and prevention of COVID-19), but it is not framed using a formal question-formulation framework (e.g., PICO, SPIDER)."
    },
    {
      "element_id": "prisma_2020_4_e2",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review is a systematic review of clinical study registrations (a mapping or scoping type review of registries), not a review of intervention effects comparing specific treatments against controls, therefore PICO is not applicable."
    }
  ],
  "confidence": 95
}

{
  "item_id": "PRISMA_2020_5",
  "elements": [
    {
      "element_id": "prisma_2020_5_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "All clinical trial registrations either being planned, or currently underway to diagnose, treat or prevent COVID-19 were eligible for inclusion in the baseline results of this review. This included patients known to be infected with COVID-19 as well as healthy volunteers, healthcare workers or other patient populations where health related outcomes were assessed in the context of COVID-19. The review was not limited by outcome, language or intervention... Eligibility was not restricted to clinical trials only; no limitations on study design were applied so that all research and observational studies would be incorporated, including retrospective studies.",
      "reason": "The manuscript specifies the eligibility criteria regarding the population (COVID-19 context, various groups), interventions (not limited), and study designs (no limitations, including observational and retrospective)."
    },
    {
      "element_id": "prisma_2020_5_e2",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The review was not limited by outcome, language or intervention given the desire to capture all clinical trial registrations planning to or currently evaluating any COVID-19 diagnostic, prevention or treatment modality.",
      "reason": "The manuscript explicitly states that the review was not limited by language."
    },
    {
      "element_id": "prisma_2020_5_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a descriptive baseline study of trial registrations, not a meta-analysis or systematic review of outcome data where exclusion based on outcome reporting would be a standard methodological step."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Definitions of the study designs manually assigned to records in this review were as per the Cochrane Consumers & Communication Review Group Study Design Guide 16 . Interventional studies were categorised as 'randomised control trials (RCT)'; 'quasi-randomised trials'; or 'non-randomised interventional studies'. For observational and epidemiological research one of the following study designs were selected: 'cohort-study'; 'case report'; 'case series'; 'case-control'; 'cross-sectional'; or 'prognostic'. For any other study designs, including health services research, behavioural and social science studies, the category of 'other' was attributed. A final study design of 'diagnostic test accuracy' was assigned where the primary outcome was assessment of diagnostic methods.",
      "reason": "The manuscript specifies the categories used for grouping studies for synthesis (study design categories)."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There were no notable restrictions on study eligibility; the authors explicitly state that the review was not limited by outcome, language, or intervention, and no limitations on study design were applied."
    }
  ],
  "confidence": 100
}

